import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { MemoryRouter } from 'react-router-dom';
import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { consultasApi, medicosApi, pacientesApi } from '../../src/api';
import { ToastProvider } from '../../src/contexts/ToastContext';
import { ConsultasPage } from '../../src/pages/recepcao/ConsultasPage';

vi.mock('../../src/api', () => ({
  consultasApi: { listar: vi.fn(), confirmar: vi.fn(), cancelar: vi.fn(), falta: vi.fn(), remarcar: vi.fn() },
  medicosApi: { listar: vi.fn(), horarios: vi.fn() },
  pacientesApi: { listar: vi.fn(), criar: vi.fn() },
}));

const CONSULTAS = [
  {
    id: 1,
    inicio: '2026-10-20 14:00',
    pacienteNome: 'Ana Pereira',
    medicoNome: 'Dr. Carlos Almeida',
    especialidadeNome: 'Clínica Geral',
    valorCentavos: 15000,
    status: 'AGENDADA',
  },
  {
    id: 2,
    inicio: '2026-10-27 09:00',
    pacienteNome: 'João Santos',
    medicoNome: 'Dra. Beatriz Souza',
    especialidadeNome: 'Cardiologia',
    valorCentavos: 27000,
    status: 'AGENDADA',
  },
];

function montar() {
  return render(
    <MemoryRouter>
      <ToastProvider>
        <ConsultasPage />
      </ToastProvider>
    </MemoryRouter>,
  );
}

async function montarComLista() {
  const utils = montar();
  await screen.findByText('2 consulta(s) encontrada(s).');
  return utils;
}

function aplicarFiltros() {
  fireEvent.click(screen.getByRole('button', { name: 'Filtrar' }));
}

describe('pages/recepcao/ConsultasPage', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
    medicosApi.listar.mockResolvedValue([{ id: 1, nome: 'Dr. Carlos Almeida' }]);
    pacientesApi.listar.mockResolvedValue([
      { id: 1, nome: 'Ana Pereira', usuarioId: 10, ativo: true },
      { id: 2, nome: 'João Santos', usuarioId: 11, ativo: true },
    ]);
    consultasApi.listar.mockResolvedValue(CONSULTAS);
  });

  afterEach(() => {
    cleanup();
    localStorage.clear();
  });

  /**
   * @caso CT-INT-218
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF10.3
   * @objetivo Listar todas as consultas da clínica com paciente, médico e contagem
   * @resultadoEsperado A tabela tem as colunas Paciente e Médico e a contagem de resultados
   */
  test('ConsultasPage lista todas as consultas com paciente e médico', async () => {
    const { container } = await montarComLista();

    const cabecalho = within(container.querySelector('thead'));
    expect(cabecalho.getByText('Paciente')).toBeInTheDocument();
    expect(cabecalho.getByText('Médico')).toBeInTheDocument();
    expect(container.querySelectorAll('tbody tr')).toHaveLength(2);
  });

  /**
   * @caso CT-INT-219
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF10.3
   * @objetivo Refazer a listagem com os filtros aplicados pela recepção
   * @resultadoEsperado Filtrar chama a API de novo com dataInicio e status escolhidos
   */
  test('ConsultasPage refaz a listagem com os filtros aplicados', async () => {
    await montarComLista();

    fireEvent.change(screen.getByLabelText('De'), { target: { value: '2026-10-01' } });
    fireEvent.change(screen.getByLabelText('Status'), { target: { value: 'AGENDADA' } });
    aplicarFiltros();

    await waitFor(() => expect(consultasApi.listar).toHaveBeenCalledTimes(2));
    expect(consultasApi.listar).toHaveBeenLastCalledWith({
      dataInicio: '2026-10-01',
      dataFim: '',
      status: 'AGENDADA',
      medicoId: '',
      pacienteId: '',
    });
  });

  /**
   * @caso CT-INT-220
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Oferecer limpar os filtros somente quando há filtro aplicado
   * @resultadoEsperado O botão Limpar aparece após filtrar e, ao ser clicado, zera os parâmetros
   */
  test('ConsultasPage só mostra Limpar com filtro ativo e zera os parâmetros', async () => {
    await montarComLista();

    expect(screen.queryByRole('button', { name: 'Limpar' })).not.toBeInTheDocument();

    fireEvent.change(screen.getByLabelText('Status'), { target: { value: 'AGENDADA' } });
    aplicarFiltros();
    await waitFor(() => expect(consultasApi.listar).toHaveBeenCalledTimes(2));

    fireEvent.click(screen.getByRole('button', { name: 'Limpar' }));

    await waitFor(() => expect(consultasApi.listar).toHaveBeenCalledTimes(3));
    expect(consultasApi.listar).toHaveBeenLastCalledWith({
      dataInicio: '',
      dataFim: '',
      status: '',
      medicoId: '',
      pacienteId: '',
    });
  });

  /**
   * @caso CT-INT-221
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.5, RN29
   * @objetivo Registrar a falta do paciente pela recepção a partir da linha da consulta
   * @resultadoEsperado O botão Falta chama a API com o id e exibe o aviso com o nome do paciente
   */
  test('ConsultasPage registra falta do paciente pela linha da consulta', async () => {
    consultasApi.falta.mockResolvedValue({ id: 1, status: 'FALTA' });
    const { container } = await montarComLista();

    fireEvent.click(container.querySelector('tr[data-consulta-id="1"] [data-acao="falta"]'));

    await waitFor(() => expect(consultasApi.falta).toHaveBeenCalledWith(1));
    expect(await screen.findByText('Falta registrada para Ana Pereira.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-222
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.2, RN26
   * @objetivo Exigir motivo ao cancelar pela recepção e enviá-lo à API
   * @resultadoEsperado O diálogo pede o motivo e cancelar é chamado com id e texto digitado
   */
  test('ConsultasPage cancela com motivo informado pela recepção', async () => {
    consultasApi.cancelar.mockResolvedValue({ id: 2, status: 'CANCELADA' });
    const { container } = await montarComLista();

    fireEvent.click(container.querySelector('tr[data-consulta-id="2"] [data-acao="cancelar"]'));
    await screen.findByRole('dialog', { name: 'Cancelar consulta' });
    fireEvent.change(screen.getByLabelText('Motivo do cancelamento'), { target: { value: 'Paciente desistiu' } });
    fireEvent.click(screen.getByRole('button', { name: 'Cancelar consulta' }));

    await waitFor(() => expect(consultasApi.cancelar).toHaveBeenCalledWith(2, 'Paciente desistiu'));
    expect(await screen.findByText('Consulta cancelada.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-223
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Mostrar a falha da listagem como alerta em português na página
   * @resultadoEsperado Erro da API vira alerta com o id da mensagem da página
   */
  test('ConsultasPage exibe o erro da listagem como alerta', async () => {
    consultasApi.listar.mockRejectedValue(new Error('Status inválido.'));

    montar();

    const aviso = await screen.findByRole('alert');
    expect(aviso).toHaveAttribute('id', 'consultas-mensagem');
    expect(aviso).toHaveTextContent('Status inválido.');
  });
});

frontend/__testes__/integracao/seletor-h.source:
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { medicosApi } from '../../src/api';
import { SeletorHorarios } from '../../src/components/SeletorHorarios';

vi.mock('../../src/api', () => ({
  medicosApi: { horarios: vi.fn() },
}));

function montar(props = {}) {
  return render(
    <SeletorHorarios
      id="agendar-horarios"
      medicoId="1"
      data="2026-10-26"
      selecionado={null}
      onEscolher={vi.fn()}
      recarregarChave={0}
      {...props}
    />,
  );
}

describe('components/SeletorHorarios', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(cleanup);

  /**
   * @caso CT-INT-180
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF07.1
   * @objetivo Não consultar a API quando o usuário ainda não escolheu médico e data
   * @resultadoEsperado Sem médico ou data, nenhuma chamada é feita e o grupo fica vazio
   */
  test('SeletorHorarios não busca horários sem médico ou sem data', () => {
    montar({ medicoId: '', data: '' });

    expect(medicosApi.horarios).not.toHaveBeenCalled();
    const grupo = document.getElementById('agendar-horarios');
    expect(grupo).toHaveAttribute('aria-busy', 'false');
    expect(grupo.querySelectorAll('button')).toHaveLength(0);
  });

  /**
   * @caso CT-INT-181
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF07.1, RN14
   * @objetivo Listar os horários livres devolvidos pela API como botões escolhíveis
   * @resultadoEsperado Os horários viram botões com data-inicio e a hora visível no rótulo
   */
  test('SeletorHorarios lista os horários devolvidos pela API', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });

    montar();

    expect(medicosApi.horarios).toHaveBeenCalledWith('1', '2026-10-26');
    expect(await screen.findByRole('button', { name: '08:00' })).toHaveAttribute('data-inicio', '2026-10-26 08:00');
    expect(screen.getByRole('button', { name: '08:30' })).toHaveAttribute('data-inicio', '2026-10-26 08:30');
  });

  /**
   * @caso CT-INT-182
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Avisar em português quando não há nenhum horário livre na data
   * @resultadoEsperado Lista vazia mostra o aviso "Nenhum horário livre nesta data. Tente outro dia."
   */
  test('SeletorHorarios avisa quando a data não tem horários livres', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: [] });

    montar({ data: '2026-10-27' });

    expect(await screen.findByText('Nenhum horário livre nesta data. Tente outro dia.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-183
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Exibir a mensagem de erro da API sem quebrar o formulário de agendamento
   * @resultadoEsperado Falha na busca aparece como aviso com o texto do erro
   */
  test('SeletorHorarios exibe o erro da API como aviso', async () => {
    medicosApi.horarios.mockRejectedValue(new Error('Data inválida. Use o formato AAAA-MM-DD.'));

    montar({ data: '2026-13-40' });

    expect(await screen.findByText('Data inválida. Use o formato AAAA-MM-DD.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-184
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN17
   * @objetivo Entregar o horário escolhido integralmente ao formulário de agendamento
   * @resultadoEsperado Clicar no botão chama onEscolher com "AAAA-MM-DD HH:mm" completo
   */
  test('SeletorHorarios entrega o horário completo ao clicar', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });
    const aoEscolher = vi.fn();

    montar({ onEscolher: aoEscolher });

    fireEvent.click(await screen.findByRole('button', { name: '08:30' }));

    expect(aoEscolher).toHaveBeenCalledWith('2026-10-26 08:30');
  });

  /**
   * @caso CT-INT-185
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RNF06
   * @objetivo Destacar o horário já escolhido pelo usuário
   * @resultadoEsperado O horário selecionado tem aria-pressed true e a classe selecionado
   */
  test('SeletorHorarios marca com aria-pressed o horário selecionado', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });

    montar({ selecionado: '2026-10-26 08:00' });

    const escolhido = await screen.findByRole('button', { name: '08:00' });
    expect(escolhido).toHaveAttribute('aria-pressed', 'true');
    expect(escolhido).toHaveClass('selecionado');
    expect(screen.getByRole('button', { name: '08:30' })).toHaveAttribute('aria-pressed', 'false');
  });

  /**
   * @caso CT-INT-186
   * @nivel integracao
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Recarregar os horários quando a página pede (após um novo agendamento)
   * @resultadoEsperado Mudar recarregarChave dispara uma nova chamada à API de horários
   */
  test('SeletorHorarios busca de novo ao mudar recarregarChave', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00'] });

    const { rerender } = render(
      <SeletorHorarios id="agendar-horarios" medicoId="1" data="2026-10-26" selecionado={null} onEscolher={vi.fn()} recarregarChave={0} />,
    );
    await screen.findByRole('button', { name: '08:00' });

    rerender(
      <SeletorHorarios id="agendar-horarios" medicoId="1" data="2026-10-26" selecionado={null} onEscolher={vi.fn()} recarregarChave={1} />,
    );

    await waitFor(() => expect(medicosApi.horarios).toHaveBeenCalledTimes(2));
  });

  /**
   * @caso CT-INT-187
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Anunciar o grupo como ocupado enquanto os horários carregam
   * @resultadoEsperado aria-busy fica true durante a busca e volta a false ao concluir
   */
  test('SeletorHorarios mantém aria-busy true enquanto carrega', async () => {
    let resolver;
    medicosApi.horarios.mockReturnValue(new Promise((resolverExterno) => { resolver = resolverExterno; }));

    montar();

    expect(document.getElementById('agendar-horarios')).toHaveAttribute('aria-busy', 'true');
    resolver({ horarios: [] });
    await waitFor(() => expect(document.getElementById('agendar-horarios')).toHaveAttribute('aria-busy', 'false'));
  });
});

