import { afterEach, describe, expect, test, vi } from 'vitest';
import {
  NOMES_DIAS,
  STATUS_CONSULTA,
  estaAtiva,
  formatarDataHora,
  formatarMoeda,
  hojeISO,
} from '../../src/utils/formatadores';

// O toLocaleString('pt-BR') usa um espaço não separável entre "R$" e o valor.
const moeda = (centavos) => formatarMoeda(centavos).replace(/\u00a0/g, ' ');

describe('utils/formatadores', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  /**
   * @caso CT-UNI-128
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN22, RF08.2
   * @objetivo Exibir o preço base da especialidade em reais no formato brasileiro
   * @resultadoEsperado formatarMoeda(15000) devolve "R$ 150,00"
   */
  test('formatarMoeda converte centavos em reais no formato pt-BR', () => {
    expect(moeda(15000)).toBe('R$ 150,00');
  });

  /**
   * @caso CT-UNI-129
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN24
   * @objetivo Exibir valor zero de retorno gratuito sem casas decimais estranhas
   * @resultadoEsperado formatarMoeda(0) devolve "R$ 0,00"
   */
  test('formatarMoeda mostra zero para o retorno gratuito', () => {
    expect(moeda(0)).toBe('R$ 0,00');
  });

  /**
   * @caso CT-UNI-130
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN23
   * @objetivo Exibir o valor com desconto de 10% do paciente idoso já arredondado
   * @resultadoEsperado formatarMoeda(27000) devolve "R$ 270,00"
   */
  test('formatarMoeda exibe o valor do desconto do paciente idoso', () => {
    expect(moeda(27000)).toBe('R$ 270,00');
  });

  /**
   * @caso CT-UNI-131
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter data e hora do padrão do sistema para o formato brasileiro com hora
   * @resultadoEsperado formatarDataHora("2026-10-19 08:30") devolve "19/10/2026 08:30"
   */
  test('formatarDataHora converte data e hora para DD/MM/AAAA HH:mm', () => {
    expect(formatarDataHora('2026-10-19 08:30')).toBe('19/10/2026 08:30');
  });

  /**
   * @caso CT-UNI-132
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter apenas a data sem inventar uma hora
   * @resultadoEsperado formatarDataHora("2026-10-19") devolve "19/10/2026"
   */
  test('formatarDataHora converte data sem hora para DD/MM/AAAA', () => {
    expect(formatarDataHora('2026-10-19')).toBe('19/10/2026');
  });

  /**
   * @caso CT-UNI-133
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF06
   * @objetivo Tratar entrada vazia de data sem lançar exceção
   * @resultadoEsperado formatarDataHora("") devolve string vazia
   */
  test('formatarDataHora devolve string vazia para entrada vazia', () => {
    expect(formatarDataHora('')).toBe('');
  });

  /**
   * @caso CT-UNI-134
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF06
   * @objetivo Tratar data nula ou indefinida sem lançar exceção
   * @resultadoEsperado formatarDataHora(null) e formatarDataHora(undefined) devolvem string vazia
   */
  test('formatarDataHora devolve string vazia para null e undefined', () => {
    expect(formatarDataHora(null)).toBe('');
    expect(formatarDataHora(undefined)).toBe('');
  });

  /**
   * @caso CT-UNI-135
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF09
   * @objetivo Disponibilizar todos os status da máquina de estados da consulta
   * @resultadoEsperado STATUS_CONSULTA lista AGENDADA, CONFIRMADA, REALIZADA, FALTA e CANCELADA nessa ordem
   */
  test('STATUS_CONSULTA cobre todos os status da máquina de estados', () => {
    expect(STATUS_CONSULTA).toEqual(['AGENDADA', 'CONFIRMADA', 'REALIZADA', 'FALTA', 'CANCELADA']);
  });

  /**
   * @caso CT-UNI-136
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN19
   * @objetivo Considerar consulta AGENDADA como ativa para os limites do paciente
   * @resultadoEsperado estaAtiva({ status: "AGENDADA" }) devolve true
   */
  test('estaAtiva reconhece consulta AGENDADA como ativa', () => {
    expect(estaAtiva({ status: 'AGENDADA' })).toBe(true);
  });

  /**
   * @caso CT-UNI-137
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN19
   * @objetivo Considerar consulta CONFIRMADA como ativa para os limites do paciente
   * @resultadoEsperado estaAtiva({ status: "CONFIRMADA" }) devolve true
   */
  test('estaAtiva reconhece consulta CONFIRMADA como ativa', () => {
    expect(estaAtiva({ status: 'CONFIRMADA' })).toBe(true);
  });

  /**
   * @caso CT-UNI-138
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN26
   * @objetivo Não tratar estados finais da consulta como ativos
   * @resultadoEsperado estaAtiva devolve false para REALIZADA, FALTA e CANCELADA
   */
  test('estaAtiva devolve false para os estados finais', () => {
    const resultados = ['REALIZADA', 'FALTA', 'CANCELADA'].map((status) => estaAtiva({ status }));
    expect(resultados).toEqual([false, false, false]);
  });

  /**
   * @caso CT-UNI-139
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF05.1
   * @objetivo Disponibilizar os nomes dos dias da semana em português para a grade
   * @resultadoEsperado NOMES_DIAS tem 7 posições começando em "Domingo" e terminando em "Sábado"
   */
  test('NOMES_DIAS cobre a semana começando no domingo', () => {
    expect(NOMES_DIAS).toHaveLength(7);
    expect(NOMES_DIAS[0]).toBe('Domingo');
    expect(NOMES_DIAS[6]).toBe('Sábado');
  });

  /**
   * @caso CT-UNI-140
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Permitir fixar o relógio para testar o cálculo da data de hoje
   * @resultadoEsperado Com o relógio fixado em 2026-10-19T08:00:00, hojeISO devolve "2026-10-19"
   */
  test('hojeISO usa o relógio injetável e devolve a data no formato AAAA-MM-DD', () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date('2026-10-19T08:00:00'));
    expect(hojeISO()).toBe('2026-10-19');
  });
});

frontend/__testes__/unitario/auth-contex.source:
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { cleanup, fireEvent, render, renderHook, screen, waitFor } from '@testing-library/react';
import { authApi } from '../../src/api';
import { AuthProvider, ROTA_INICIAL, useAuth } from '../../src/contexts/AuthContext';

vi.mock('../../src/api', () => ({
  authApi: { login: vi.fn(), me: vi.fn(), registrar: vi.fn() },
}));

function Sonda() {
  const { usuario, carregando, entrar, sair } = useAuth();
  return (
    <div>
      <span data-testid="usuario">{usuario ? `${usuario.perfil}:${usuario.nome}` : 'nenhum'}</span>
      <span data-testid="carregando">{String(carregando)}</span>
      <button type="button" onClick={() => entrar('ana@email.com', 'Senha123')}>entrar</button>
      <button type="button" onClick={sair}>sair</button>
    </div>
  );
}

describe('contexts/AuthContext', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  afterEach(() => {
    cleanup();
    localStorage.clear();
  });

  /**
   * @caso CT-UNI-164
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Falhar de forma previsível quando o hook é usado fora do provedor
   * @resultadoEsperado useAuth() devolve null sem AuthProvider na árvore
   */
  test('useAuth devolve null quando usado sem AuthProvider', () => {
    const { result } = renderHook(() => useAuth());

    expect(result.current).toBeNull();
  });

  /**
   * @caso CT-UNI-165
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RF01.2
   * @objetivo Não consultar dados do usuário quando não há sessão salva
   * @resultadoEsperado Sem token, /auth/me não é chamado, carregando é false e usuário fica null
   */
  test('AuthProvider não chama /auth/me sem token no armazenamento', () => {
    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
    expect(screen.getByTestId('usuario')).toHaveTextContent('nenhum');
    expect(authApi.me).not.toHaveBeenCalled();
  });

  /**
   * @caso CT-UNI-166
   * @nivel unitario
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.3
   * @objetivo Restaurar a sessão do usuário a partir do token salvo
   * @resultadoEsperado Com token, /auth/me é chamado uma vez e define o usuário logado
   */
  test('AuthProvider restaura a sessão chamando /auth/me com token salvo', async () => {
    localStorage.setItem('clinica.token', 'tok-1');
    authApi.me.mockResolvedValue({ id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' });

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    expect(screen.getByTestId('carregando')).toHaveTextContent('true');
    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('PACIENTE:Ana Pereira'));
    expect(authApi.me).toHaveBeenCalledTimes(1);
    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
  });

  /**
   * @caso CT-UNI-167
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo recuperabilidade
   * @requisito RNF02
   * @objetivo Descartar a sessão quando o token salvo é rejeitado pela API
   * @resultadoEsperado /auth/me rejeitado limpa o token, zera o usuário e encerra o carregamento
   */
  test('AuthProvider descarta a sessão quando /auth/me rejeita', async () => {
    localStorage.setItem('clinica.token', 'tok-invalido');
    authApi.me.mockRejectedValue(new Error('Token inválido ou expirado.'));

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('nenhum'));
    expect(localStorage.getItem('clinica.token')).toBeNull();
    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
  });

  /**
   * @caso CT-UNI-168
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RF01.1
   * @objetivo Guardar o token recebido no login e manter o usuário em memória
   * @resultadoEsperado entrar chama o login com as credenciais, salva o token e define o usuário
   */
  test('entrar autentica, salva o token e define o usuário', async () => {
    authApi.login.mockResolvedValue({
      token: 'tok-novo',
      usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' },
    });

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    fireEvent.click(screen.getByText('entrar'));

    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('PACIENTE:Ana Pereira'));
    expect(authApi.login).toHaveBeenCalledWith('ana@email.com', 'Senha123');
    expect(localStorage.getItem('clinica.token')).toBe('tok-novo');
  });

  /**
   * @caso CT-UNI-169
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RNF02
   * @objetivo Encerrar a sessão removendo o token do navegador
   * @resultadoEsperado sair apaga o token e zera o usuário em memória
   */
  test('sair remove o token e zera o usuário', async () => {
    authApi.login.mockResolvedValue({
      token: 'tok-1',
      usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' },
    });

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    fireEvent.click(screen.getByText('entrar'));
    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('PACIENTE:Ana Pereira'));

    fireEvent.click(screen.getByText('sair'));

    expect(screen.getByTestId('usuario')).toHaveTextContent('nenhum');
    expect(localStorage.getItem('clinica.token')).toBeNull();
  });

  /**
   * @caso CT-UNI-170
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN30
   * @objetivo Direcionar cada perfil para a rota inicial que lhe corresponde
   * @resultadoEsperado ROTA_INICIAL mapeia PACIENTE, MEDICO e RECEPCAO para as rotas da aplicação
   */
  test('ROTA_INICIAL mapeia os três perfis para as rotas corretas', () => {
    expect(ROTA_INICIAL).toEqual({
      PACIENTE: '/paciente',
      MEDICO: '/medico',
      RECEPCAO: '/recepcao',
    });
  });
});

frontend/__testes__/unitario/use-carrega.source:
import { afterEach, describe, expect, test, vi } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { useCarregar } from '../../src/hooks/useCarregar';

function Sonda({ funcao, dependencias = [] }) {
  const { dados, erro, carregando, recarregar } = useCarregar(funcao, dependencias);
  return (
    <div>
      <span data-testid="carregando">{String(carregando)}</span>
      <span data-testid="dados">{dados === null ? 'sem-dados' : JSON.stringify(dados)}</span>
      <span data-testid="erro">{erro ?? 'sem-erro'}</span>
      <button type="button" onClick={recarregar}>recarregar</button>
    </div>
  );
}

describe('hooks/useCarregar', () => {
  afterEach(cleanup);

  /**
   * @caso CT-UNI-155
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Expor o estado de carregamento enquanto a promessa não resolve
   * @resultadoEsperado Ao montar, carregando é true e vira false quando a função conclui
   */
  test('useCarregar inicia com carregando true e encerra quando a função conclui', async () => {
    let resolver;
    const promessa = new Promise((resolverExterno) => { resolver = resolverExterno; });
    const funcao = vi.fn(() => promessa);

    render(<Sonda funcao={funcao} />);

    expect(screen.getByTestId('carregando')).toHaveTextContent('true');
    resolver({ lista: [] });
    await waitFor(() => expect(screen.getByTestId('carregando')).toHaveTextContent('false'));
    expect(funcao).toHaveBeenCalledTimes(1);
  });

  /**
   * @caso CT-UNI-156
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF10.3
   * @objetivo Guardar os dados devolvidos pela função assíncrona
   * @resultadoEsperado dados recebe o resultado da função e carregando fica false
   */
  test('useCarregar preenche dados com o resultado da função', async () => {
    const funcao = vi.fn(() => Promise.resolve({ id: 1, nome: 'Ana Pereira' }));

    render(<Sonda funcao={funcao} />);

    await waitFor(() => expect(screen.getByTestId('dados')).toHaveTextContent('"nome":"Ana Pereira"'));
    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
    expect(screen.getByTestId('erro')).toHaveTextContent('sem-erro');
  });

  /**
   * @caso CT-UNI-157
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Capturar a falha da função sem derrubar a renderização
   * @resultadoEsperado erro recebe a mensagem, dados permanece null e carregando fica false
   */
  test('useCarregar registra o erro sem lançar exceção', async () => {
    const funcao = vi.fn(() => Promise.reject(new Error('Falha ao carregar.')));

    render(<Sonda funcao={funcao} />);

    await waitFor(() => expect(screen.getByTestId('erro')).toHaveTextContent('Falha ao carregar.'));
    expect(screen.getByTestId('dados')).toHaveTextContent('sem-dados');
    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
  });

  /**
   * @caso CT-UNI-158
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Permitir recarregar a lista e limpar o erro anterior
   * @resultadoEsperado recarregar executa a função de novo e zera o erro anterior
   */
  test('useCarregar.recarregar executa a função outra vez e limpa o erro', async () => {
    const funcao = vi.fn()
      .mockRejectedValueOnce(new Error('Falha transitoria.'))
      .mockResolvedValueOnce({ ok: true });

    render(<Sonda funcao={funcao} />);
    await waitFor(() => expect(screen.getByTestId('erro')).toHaveTextContent('Falha transitoria.'));

    fireEvent.click(screen.getByText('recarregar'));

    await waitFor(() => expect(screen.getByTestId('dados')).toHaveTextContent('"ok":true'));
    expect(funcao).toHaveBeenCalledTimes(2);
    expect(screen.getByTestId('erro')).toHaveTextContent('sem-erro');
  });

  /**
   * @caso CT-UNI-159
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF10.3
   * @objetivo Executar a função de novo quando as dependências mudam
   * @resultadoEsperado Trocar a dependência dispara nova chamada com o valor atualizado
   */
  test.skip('useCarregar refaz a chamada quando as dependências mudam', async () => {
    const funcao = vi.fn((chave) => Promise.resolve({ chave }));

    const { rerender } = render(<Sonda funcao={funcao} dependencias={['a']} />);
    await waitFor(() => expect(funcao).toHaveBeenCalledWith('a'));

    rerender(<Sonda funcao={funcao} dependencias={['b']} />);

    await waitFor(() => expect(funcao).toHaveBeenCalledWith('b'));
    expect(funcao).toHaveBeenCalledTimes(2);
  });
});

