import { afterEach, describe, expect, test, vi } from 'vitest';
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { DialogoTexto } from '../../src/components/DialogoTexto';

function montar(props = {}) {
  const aoConfirmar = vi.fn();
  const aoCancelar = vi.fn();
  render(
    <DialogoTexto
      titulo="Cancelar consulta"
      descricao="Ana Pereira · 26/10/2026 08:00. O motivo é obrigatório."
      rotulo="Motivo do cancelamento"
      textoConfirmar="Cancelar consulta"
      perigo
      onConfirmar={aoConfirmar}
      onCancelar={aoCancelar}
      {...props}
    />,
  );
  return { aoConfirmar, aoCancelar };
}

afterEach(cleanup);

describe('components/DialogoTexto', () => {
  /**
   * @caso CT-INT-224
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Apresentar o pedido de texto com rótulo, descrição e campo associados
   * @resultadoEsperado O diálogo exibe título, descrição e textarea acessível pelo rótulo
   */
  test('DialogoTexto exibe título, descrição e campo com rótulo associado', () => {
    montar();

    expect(screen.getByRole('dialog', { name: 'Cancelar consulta' })).toBeInTheDocument();
    expect(screen.getByText('Ana Pereira · 26/10/2026 08:00. O motivo é obrigatório.')).toBeInTheDocument();
    expect(screen.getByLabelText('Motivo do cancelamento')).toHaveAttribute('id', 'texto-campo');
  });

  /**
   * @caso CT-INT-225
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.2
   * @objetivo Entregar o motivo digitado à confirmação do cancelamento
   * @resultadoEsperado Confirmar chama onConfirmar com exatamente o texto digitado
   */
  test('DialogoTexto entrega o texto digitado ao confirmar', () => {
    const { aoConfirmar } = montar();

    fireEvent.change(screen.getByLabelText('Motivo do cancelamento'), { target: { value: 'Não vou comparecer' } });
    fireEvent.click(screen.getByRole('button', { name: 'Cancelar consulta' }));

    expect(aoConfirmar).toHaveBeenCalledWith('Não vou comparecer');
  });

  /**
   * @caso CT-INT-226
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Permite desistir da ação sem disparar a confirmação
   * @resultadoEsperado "Voltar" chama onCancelar e não chama onConfirmar
   */
  test('DialogoTexto desiste da ação ao clicar em Voltar', () => {
    const { aoConfirmar, aoCancelar } = montar();

    fireEvent.click(screen.getByRole('button', { name: 'Voltar' }));

    expect(aoCancelar).toHaveBeenCalledTimes(1);
    expect(aoConfirmar).not.toHaveBeenCalled();
  });
});

frontend/__testes__/integracao/mensagem..source:
import { afterEach, describe, expect, test } from 'vitest';
import { cleanup, render, screen } from '@testing-library/react';
import { Mensagem } from '../../src/components/Mensagem';

afterEach(cleanup);

describe('components/Mensagem', () => {
  /**
   * @caso CT-INT-152
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Não ocupar espaço na tela quando não há mensagem a exibir
   * @resultadoEsperado Com mensagem null, Mensagem não renderiza elemento algum
   */
  test('Mensagem não renderiza nada quando a mensagem é null', () => {
    const { container } = render(<Mensagem id="login-mensagem" mensagem={null} />);
    expect(container.innerHTML).toBe('');
  });

  /**
   * @caso CT-INT-153
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Exibir o erro de login como alerta legível junto ao formulário
   * @resultadoEsperado Mensagem de erro vira região de alerta com o texto em português
   */
  test('Mensagem de erro vira role alert com o texto informado', () => {
    render(<Mensagem id="login-mensagem" mensagem={{ tipo: 'erro', texto: 'E-mail ou senha inválidos.' }} />);
    const aviso = screen.getByRole('alert');
    expect(aviso).toHaveAttribute('id', 'login-mensagem');
    expect(aviso).toHaveClass('mensagem', 'erro');
    expect(aviso).toHaveTextContent('E-mail ou senha inválidos.');
  });

  /**
   * @caso CT-INT-154
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RNF06
   * @objetivo Anunciar a mensagem de sucesso para leitores de tela
   * @resultadoEsperado Mensagem de sucesso vira role status com o texto informado
   */
  test('Mensagem de sucesso vira role status com o texto informado', () => {
    render(<Mensagem id="agendar-mensagem" mensagem={{ tipo: 'sucesso', texto: 'Consulta agendada.' }} />);
    const aviso = screen.getByRole('status');
    expect(aviso).toHaveAttribute('id', 'agendar-mensagem');
    expect(aviso).toHaveClass('mensagem', 'sucesso');
    expect(aviso).toHaveTextContent('Consulta agendada.');
  });
});

